protected <T> @Nullable T getProperty(String key, Class<T> targetValueType, boolean resolveNestedPlaceholders) {
	if (this.propertySources != null) {
		for (PropertySource<?> propertySource : this.propertySources) {
			if (logger.isTraceEnabled()) {
				logger.trace("Searching for key '" + key + "' in PropertySource '" +
						propertySource.getName() + "'");
			}
			Object value = propertySource.getProperty(key);
			if (value != null) {
				if (resolveNestedPlaceholders) {
					if (value instanceof String string) {
						value = resolveNestedPlaceholders(string);
					}
					else if ((value instanceof CharSequence cs) && (String.class.equals(targetValueType) ||
							CharSequence.class.equals(targetValueType))) {
						value = resolveNestedPlaceholders(cs.toString());
					}
				}
				logKeyFound(key, propertySource, value);
				return convertValueIfNecessary(value, targetValueType);
			}
		}
	}
	if (logger.isTraceEnabled()) {
		logger.trace("Could not find key '" + key + "' in any property source");
	}
	return null;
}

@Override
public String resolveRequiredPlaceholders(String text) throws IllegalArgumentException {
	if (this.strictHelper == null) {
		this.strictHelper = createPlaceholderHelper(false);
	}
	return doResolvePlaceholders(text, this.strictHelper);
}

/**
 * Resolve placeholders within the given string, deferring to the value of
 * {@link #setIgnoreUnresolvableNestedPlaceholders} to determine whether any
 * unresolvable placeholders should raise an exception or be ignored.
 * <p>Invoked from {@link #getProperty} and its variants, implicitly resolving
 * nested placeholders. In contrast, {@link #resolvePlaceholders} and
 * {@link #resolveRequiredPlaceholders} do <i>not</i> delegate
 * to this method but rather perform their own handling of unresolvable
 * placeholders, as specified by each of those methods.
 * @since 3.2
 * @see #setIgnoreUnresolvableNestedPlaceholders
 */
protected String resolveNestedPlaceholders(String value) {
	if (value.isEmpty()) {
		return value;
	}
	return (this.ignoreUnresolvableNestedPlaceholders ?
			resolvePlaceholders(value) : resolveRequiredPlaceholders(value));
}

private PropertyPlaceholderHelper createPlaceholderHelper(boolean ignoreUnresolvablePlaceholders) {
	return new PropertyPlaceholderHelper(this.placeholderPrefix, this.placeholderSuffix,
			this.valueSeparator, this.escapeCharacter, ignoreUnresolvablePlaceholders);
}

private String doResolvePlaceholders(String text, PropertyPlaceholderHelper helper) {
	return helper.replacePlaceholders(text, this::getPropertyAsRawString);
}

@SuppressWarnings("unchecked")
protected <T> @Nullable T convertValueIfNecessary(Object value, @Nullable Class<T> targetType) {
	if (targetType == null) {
		return (T) value;
	}
	ConversionService conversionServiceToUse = this.conversionService;
	if (conversionServiceToUse == null) {
		// Avoid initialization of shared DefaultConversionService if
		// no standard type conversion is needed in the first place...
		if (ClassUtils.isAssignableValue(targetType, value)) {
			return (T) value;
		}
		conversionServiceToUse = DefaultConversionService.getSharedInstance();
	}
	return conversionServiceToUse.convert(value, targetType);
}

@Override
public <T> T getProperty(String key, Class<T> targetType, T defaultValue) {
	T value = getProperty(key, targetType);
	return (value != null ? value : defaultValue);
}

@Override
public String getRequiredProperty(String key) throws IllegalStateException {
	String value = getProperty(key);
	if (value == null) {
		throw new IllegalStateException("Required key '" + key + "' not found");
	}
	return value;
}

@Override
public <T> T getRequiredProperty(String key, Class<T> valueType) throws IllegalStateException {
	T value = getProperty(key, valueType);
	if (value == null) {
		throw new IllegalStateException("Required key '" + key + "' not found");
	}
	return value;
}
